-- UI-7 (story 15): buttons and click callbacks. Exposed as core.ui.button on the connect API:
--   create{ id = <string>, label = <string|number|nil>, place = <intent>, style = <style|nil>, onClick = <function>,
--           enabled = <boolean|nil> } -> handle
--   setLabel(handle, label)        setEnabled(handle, enabled)       setVisible(handle, visible)
--   remove(handle)                 isShown(handle) -> boolean        stats() -> table (diagnostic copy, not semver API)
--
-- The widget is WBP_<Core>Button (Button "Btn" -> TextBlock "Label"), generated by CoreGen: SetLabel, SetEnabledState,
-- SetColors (face, hover and pressed colours plus padding: the theme's button presets), SetTag, and a Blueprint function
-- <Core>_OnClicked() that the button's OnClicked calls and that does nothing else but count (ClickCount). This is
-- bp-spike's proven pattern (docs/blueprint-mods.md Q3).
--
-- Dispatch: each dependent's Lua state registers ONE RegisterHook post-hook on <class path>:<Core>_OnClicked, by full
-- path, the first time it creates a button (core loads the button class before it calls onReady, story 15 decision 4).
-- UE4SS keys script hooks by the function's name chain, so the hook outlives a class unload and reload; one per state,
-- so no doubled hook. The hook reads the clicked widget's tag (<core>:<mod>:<id>, in CoreTag) and runs onClick only for
-- this mod's own button whose current widget it is; another mod's button is ignored in silence. onClick(handle) runs on
-- the game thread inside pcall: a throwing callback is logged once per button and the hook stays. Clicks on a disabled
-- or hidden button (or one in a hidden panel) are dropped, and so is a repeat within 250 ms (a double click is one).
--
-- Where: only on hosts where the game shows a cursor ("journal", story 13), directly or in a panel there. On the HUD
-- the game's input is game-only and clicks never reach a widget (docs/blueprint-mods.md Q3): host = "hud" raises until
-- story 16 (input mode) lands.
local BASE = (...):gsub("%.ui%.button$", "")
local C = require(BASE .. ".ui.common")
local P = require(BASE .. ".ui.place")
local X = require(BASE .. ".ui.text")
local theme = require(BASE .. ".ui.theme")

local B = {}
local MAX_LABEL = 64
local DEBOUNCE_US = 250000
local S = { clicks = 0, dropped = 0, debounced = 0, ignored = 0, throws = 0, hooked = false, hookTries = 0, hookId = nil }
local CREATE_KEYS = { id = true, label = true, place = true, style = true, onClick = true, enabled = true }

local function firstLine(e) return (tostring(e):match("^[^\n]*")) end

-- ---------------------------------------------------------------- the click hook (one per Lua state)

local function dispatch(ctx)
    local w = ctx:get()
    if not C.valid(w) then return end
    local tag = X._readTag(w, "button")
    local mine = C.LOWER .. ":" .. C.modTag .. ":"
    if not tag or tag:sub(1, #mine) ~= mine then S.ignored = S.ignored + 1 return end -- another mod's button
    local el = C.els[tag:sub(#mine + 1)]
    if not el or el.removed or el.kind ~= "button" then S.ignored = S.ignored + 1 return end
    local cur = el.ref and C.deref(el.ref)
    if not cur or cur:GetAddress() ~= w:GetAddress() then S.ignored = S.ignored + 1 return end -- not its live widget
    if not el.enabled or not el.visible or (el.panel and not el.panel.visible) then S.dropped = S.dropped + 1 return end
    local now = C.micros()
    if el.lastClick and now - el.lastClick < DEBOUNCE_US then S.debounced = S.debounced + 1 return end
    el.lastClick = now
    S.clicks = S.clicks + 1
    el.clicks = (el.clicks or 0) + 1
    if C.debugOn() then C.log.debug("ui button '%s' clicked (%d)", el.id, el.clicks) end
    local ok, err = pcall(el.onClick, el.handle)
    if not ok then
        S.throws = S.throws + 1
        if not el.warnedClick then
            el.warnedClick = true
            C.log.warn("button '%s' onClick: %s", el.id, firstLine(err))
        end
    end
end

local function onClicked(ctx)
    local ok, err = pcall(dispatch, ctx)
    if not ok then C.warnOnce("click dispatch", "button click handling failed: %s (further failures not logged)", firstLine(err)) end
end

-- Registers the hook once the button class is loaded; false (and one WARN) while it can't.
local function ensureHook()
    if S.hooked then return true end
    if not X._classOf("button") then
        C.warnOnce("button hook class", "button clicks can't be hooked yet: %s is not loaded (is Content/Paks/LogicMods/%s.pak installed?); retried at the next attach", C.BUTTON_CLASS, C.NAME)
        return false
    end
    S.hookTries = S.hookTries + 1
    local ok, pre = pcall(RegisterHook, C.CLICK_FN, onClicked)
    if ok then
        S.hooked, S.hookId = true, pre
        C.log.debug("ui button click hook registered on %s (id %s)", C.CLICK_FN, tostring(pre))
    else
        C.warnOnce("button hook", "button clicks: RegisterHook(%s) failed: %s", C.CLICK_FN, firstLine(pre))
    end
    return S.hooked
end

-- ---------------------------------------------------------------- the kind (text.lua's engine)

local function applyEnabled(el, w)
    if el.appliedEnabled == el.enabled then return end
    C.count(); w:SetEnabledState(el.enabled)
    C.count(); w:SetRenderOpacity(el.enabled and 1 or theme.disabledOpacity)
    el.appliedEnabled = el.enabled
end

X.KIND.button = {
    pkg = C.BUTTON_PKG, short = C.BUTTON_SHORT, cls = C.BUTTON_CLASS,
    content = function(el, w, fresh)
        ensureHook()
        if not (fresh and el.label == "") then C.count(); w:SetLabel(el.label) end
        if fresh then el.appliedEnabled = true end -- a new widget is enabled and opaque
        applyEnabled(el, w)
    end,
    style = function(el, w)
        local s, h, p = el.style, el.style.hover, el.style.pressed
        local ok, err = pcall(function()
            C.count(); w:SetColors(s.r, s.g, s.b, s.a, h.r, h.g, h.b, h.a, p.r, p.g, p.b, p.a, s.pad)
        end)
        if not ok then C.warnOnce("style:" .. el.id, "button '%s': style not applied (is %s's pak current?): %s", el.id, C.NAME, firstLine(err)) end
    end,
}

-- Buttons need a host with a cursor; a panel holding buttons too. Called by the engine for every create and place.
X.checkHost = function(kind, host, fn, el)
    if host ~= "hud" then return end
    if kind == "button" then C.fail("%s.%s: buttons need a host with a cursor (journal); see input mode, story 16", C.UI, fn) end
    if kind == "panel" and el then
        for _, ch in ipairs(el.children) do
            if ch.kind == "button" and not ch.removed then
                C.fail("%s.%s: panel '%s' holds buttons, which need a host with a cursor (journal); see input mode, story 16", C.UI, fn, el.id)
            end
        end
    end
end

-- ---------------------------------------------------------------- validation

local function validLabel(v, fn)
    if v == nil then return "" end
    local t = type(v)
    if t == "number" then v = tostring(v)
    elseif t ~= "string" then C.fail("%s.%s: label must be a string, a number or nil, got %s", C.UI, fn, t) end
    local okL, n = pcall(utf8.len, v)
    n = (okL and n) or #v
    if n > MAX_LABEL then C.fail("%s.%s: label is %d characters, at most %d", C.UI, fn, n, MAX_LABEL) end
    return v
end

local function validEnabled(v, fn, optional)
    if v == nil and optional then return true end
    if type(v) ~= "boolean" then C.fail("%s.%s: enabled must be a boolean%s, got %s", C.UI, fn, optional and " or nil" or "", C.describe(v)) end
    return v
end

-- ---------------------------------------------------------------- public

function B.create(opts)
    C.enter("button.create")
    if type(opts) ~= "table" then C.fail("%s.button.create: expected a table { id = ..., label = ..., place = ..., onClick = ... }, got %s", C.UI, C.describe(opts)) end
    for k in pairs(opts) do
        if not CREATE_KEYS[k] then C.fail("%s.button.create: unknown key %s (valid: enabled, id, label, onClick, place, style)", C.UI, C.describe(k)) end
    end
    local id = X._validId(opts.id, "button.create")
    local label = validLabel(opts.label, "button.create")
    if type(opts.onClick) ~= "function" then C.fail("%s.button.create: onClick must be a function, got %s", C.UI, C.describe(opts.onClick)) end
    local enabled = validEnabled(opts.enabled, "button.create", true)
    if opts.place ~= nil and type(opts.place) ~= "table" then
        C.fail("%s.button.create: place must be a table or nil, got %s", C.UI, C.describe(opts.place))
    end
    local intent = opts.place or { corner = "top-right" }
    local place = P.validate(intent)
    if not place.panelEl then X.checkHost("button", place.host, "button.create") end
    local style = X.resolveStyle(opts.style, "button")
    local el = X._existing(id, "button", "button.create")
    if el then
        -- Same id: the new label, callback, enabled state, style and intent.
        el.onClick = opts.onClick
        B.setLabel(el.handle, label)
        B.setEnabled(el.handle, enabled)
        X._setStyle(el, style)
        P.place(el.handle, intent)
        return el.handle
    end
    if place.panelEl then X._checkJoin(place.panelEl, "button", "button.create") end
    ensureHook()
    el = X._new("button", id, { label = label, style = style, onClick = opts.onClick, enabled = enabled }, place)
    return el.handle
end

function B.setLabel(h, label)
    C.enter("button.setLabel")
    local el = C.element(h, "button.setLabel", "button")
    local l = validLabel(label, "button.setLabel")
    if l == el.label then return end -- no UObject call
    el.label = l
    local w = X._liveWidget(el)
    if w then
        local ok, err = pcall(function() C.count(); w:SetLabel(l) end)
        if not ok then C.warnOnce("label:" .. el.id, "button '%s': SetLabel failed: %s", el.id, firstLine(err)) end
        X._resized(el)
    end
end

function B.setEnabled(h, enabled)
    C.enter("button.setEnabled")
    local el = C.element(h, "button.setEnabled", "button")
    local e = validEnabled(enabled, "button.setEnabled", false)
    if e == el.enabled then return end
    el.enabled = e
    local w = X._liveWidget(el)
    if w then
        local ok, err = pcall(applyEnabled, el, w)
        if not ok then C.warnOnce("enabled:" .. el.id, "button '%s': SetEnabledState failed: %s", el.id, firstLine(err)) end
    end
end

function B.setVisible(h, visible)
    C.enter("button.setVisible")
    local el = C.element(h, "button.setVisible", "button")
    if type(visible) ~= "boolean" then C.fail("%s.button.setVisible: visible must be a boolean, got %s", C.UI, type(visible)) end
    X._setVisible(el, visible)
end

function B.remove(h)
    C.enter("button.remove")
    if type(h) == "table" and C.removedHandle[h] then return end -- idempotent
    local el = C.element(h, "button.remove", "button")
    X._remove(el)
end

function B.isShown(h)
    C.enter("button.isShown")
    local el = C.element(h, "button.isShown", "button")
    return X._shown(el)
end

function B.stats()
    return { clicks = S.clicks, dropped = S.dropped, debounced = S.debounced, ignored = S.ignored, throws = S.throws,
        hooked = S.hooked, hookTries = S.hookTries }
end

-- Internal (client.lua): load the button class before onReady, so the first create can register the hook at once.
function B._prepare() return X._classOf("button") ~= nil end
B._dispatch, B._S = onClicked, S -- for unit tests
return B
